() => {
  const els = Array.from(document.querySelectorAll('*'));
  const matches = els.filter(e => e.children.length === 0 && /new release/i.test(e.textContent || ''));
  return matches.map(m => ({
    tag: m.tagName,
    text: m.textContent.trim().slice(0, 200),
    parentText: (m.parentElement?.textContent || '').trim().slice(0, 300)
  }));
}

() => {
  const all = Array.from(document.querySelectorAll('*'));
  const matches = all.filter(e => /new release/i.test(e.textContent || ''));
  const visible = matches.filter(m => {
    const r = m.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  });
  return visible.slice(0, 20).map(m => ({
    tag: m.tagName,
    text: m.textContent.trim().slice(0, 250),
    top: m.getBoundingClientRect().top,
    bottom: m.getBoundingClientRect().bottom
  }));
}

() => {
  const all = Array.from(document.querySelectorAll('section, h1, h2, h3, h4, div'));
  const matches = all.filter(e => {
    const txt = (e.textContent || '').trim();
    return txt.length > 0 && txt.length < 100 && /new|release/i.test(txt);
  });
  return matches.slice(0, 30).map(m => ({
    tag: m.tagName,
    text: m.textContent.trim().slice(0, 150)
  }));
}

() => {
  // Get all section headings
  const sections = Array.from(document.querySelectorAll('section'));
  return sections.map(s => {
    const headings = Array.from(s.querySelectorAll('h1, h2, h3, h4, [data-testid*="title"], [data-testid*="heading"]'));
    return {
      sectionId: s.id || s.dataset.testid || 'unknown',
      headings: headings.map(h => h.textContent.trim()).slice(0, 5)
    };
  });
}

() => {
  // Find all sections and what their immediate children reveal
  const sections = Array.from(document.querySelectorAll('section'));
  return sections.map((s, i) => {
    // First few text-like children
    const texts = [];
    const walker = document.createTreeWalker(s, NodeFilter.SHOW_TEXT, null);
    let count = 0;
    let node;
    while ((node = walker.nextNode()) && count < 3) {
      const t = node.textContent.trim();
      if (t.length > 1 && t.length < 200) {
        texts.push(t);
        count++;
      }
    }
    return {
      idx: i,
      id: s.id,
      className: s.className?.slice(0, 80),
      firstTexts: texts
    };
  });
}

() => {
  // Get all h1, h2, h3 elements
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4, h5, h6'));
  return headings.map(h => ({
    level: h.tagName,
    text: h.textContent.trim().slice(0, 150),
    top: h.getBoundingClientRect().top + window.scrollY
  }));
}

() => {
  return {
    headings: document.querySelectorAll('h1, h2, h3, h4').length,
    sections: document.querySelectorAll('section').length,
    title: document.title,
    bodyTextLength: document.body.textContent.length
  };
}

() => {
  const h = document.querySelectorAll('h1, h2, h3, h4');
  return Array.from(h).map(x => x.outerHTML.slice(0, 200));
}

() => {
  const all = Array.from(document.querySelectorAll('h1, h2, h3, h4, h5, h6, [data-testid*="title"], [data-testid*="heading"], span, div'));
  const matches = all.filter(e => {
    if (e.children.length > 0) return false;
    const t = (e.textContent || '').trim();
    return t.toLowerCase().includes('new') || t.toLowerCase().includes('release');
  });
  return matches.slice(0, 50).map(m => ({
    tag: m.tagName,
    text: m.textContent.trim().slice(0, 200),
    top: m.getBoundingClientRect().top + window.scrollY
  }));
}

() => {
  return __find("new release").map(function(el) {
    return {
      tag: el.tagName,
      text: el.textContent.replace(/\s+/g, ' ').trim().slice(0, 200),
      index: el.getAttribute('data-hl-idx'),
      top: el.getBoundingClientRect().top + window.scrollY
    };
  });
}

() => {
  const allElements = Array.from(document.querySelectorAll('*'));
  const matches = [];
  for (const el of allElements) {
    const text = (el.textContent || '').trim();
    const ownText = Array.from(el.childNodes).filter(n => n.nodeType === Node.TEXT_NODE).map(n => n.textContent.trim()).join(' ');
    if (ownText && /new release/i.test(ownText)) {
      matches.push({
        tag: el.tagName,
        text: ownText.slice(0, 200),
        top: el.getBoundingClientRect().top + window.scrollY
      });
    }
  }
  return matches.slice(0, 20);
}

() => {
  const links = Array.from(document.querySelectorAll('a'));
  return links.filter(l => /new release/i.test(l.href) || /new release/i.test(l.textContent)).map(l => ({
    href: l.href,
    text: l.textContent.trim()
  })).slice(0, 20);
}

() => {
  const elements = document.querySelectorAll('*');
  const matches = [];
  for (const el of elements) {
    const text = (el.textContent || '').trim();
    if (/new release|newrelease/i.test(text) && text.length < 1000) {
      matches.push({
        tag: el.tagName,
        snippet: text.slice(0, 300),
        rect: el.getBoundingClientRect()
      });
    }
  }
  return matches;
}
